CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('ADMIN','LIBRARIAN','READER') DEFAULT 'READER',status ENUM('ACTIVE','LOCKED') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS readers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE,phone VARCHAR(30),address VARCHAR(255),birth_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS books(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(180) NOT NULL,isbn VARCHAR(40) UNIQUE,publisher VARCHAR(180),year SMALLINT,category_id INT,quantity INT NOT NULL DEFAULT 1,available INT NOT NULL DEFAULT 1,price DECIMAL(14,2) NOT NULL DEFAULT 0,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_books_cat FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS borrows(id INT AUTO_INCREMENT PRIMARY KEY,reader_id INT NOT NULL,book_id INT NOT NULL,borrow_date DATE NOT NULL,due_date DATE NOT NULL,return_date DATE,status ENUM('BORROWING','RETURNED','CANCELLED') DEFAULT 'BORROWING',fine_amount DECIMAL(14,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reader_id) REFERENCES readers(id),FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations(id INT AUTO_INCREMENT PRIMARY KEY,reader_id INT NOT NULL,book_id INT NOT NULL,reserve_date DATE NOT NULL,status ENUM('WAITING','READY','CANCELLED','COMPLETED') DEFAULT 'WAITING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reader_id) REFERENCES readers(id),FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchases(id INT AUTO_INCREMENT PRIMARY KEY,reader_id INT NOT NULL,book_id INT NOT NULL,quantity INT NOT NULL,total_amount DECIMAL(14,2) NOT NULL,status ENUM('PENDING','PAID','CANCELLED') DEFAULT 'PENDING',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reader_id) REFERENCES readers(id),FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fines(id INT AUTO_INCREMENT PRIMARY KEY,borrow_id INT NOT NULL,reader_id INT NOT NULL,amount DECIMAL(14,2) NOT NULL,reason VARCHAR(255),status ENUM('UNPAID','PAID') DEFAULT 'UNPAID',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(borrow_id) REFERENCES borrows(id),FOREIGN KEY(reader_id) REFERENCES readers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(80),entity VARCHAR(80),entity_id INT,detail TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE INDEX idx_books_title ON books(title);CREATE INDEX idx_borrows_status ON borrows(status,due_date);CREATE INDEX idx_readers_name ON readers(name);
